logger.info(
  {
    userId: stateData.userId,
    platform: p.name,
    username: p.username,
  },
  `[OAuth] Successfully connected ${p.name} for user`,
)

logger.info(
  `Status page subscriber added: ${subscriber?.id} - ${subscriber?.email}`,
)

logger.info(
  {
    hasAccessToken: !!tokenData.access_token,
    hasRefreshToken: !!tokenData.refresh_token,
    expiresIn: tokenData.expires_in,
  },
  `[OAuth] Twitter token exchange SUCCESS`,
)

logger.info(
  `[DNS] ✅ Authoritative nameserver online — ${BASE_DOMAIN} → ${DNS_SERVER_IP} (UDP+TCP :${DNS_PORT})`,
)

logger.info(
  `✅ Successfully deleted account: ${user?.id} (${user?.email})`,
)

logger.info(
  `[SocialSync] Instagram: @${bestIgAccount.username}, followers=${bestIgAccount?.followers_count}`,
)

logger.info(
  `Admin ${req.user?.email} banned user ${userId}. Duration: ${duration || "permanent"}. Reason: ${reason}`,
)

logger.info(
  `[AdDispatch] optimizeBidding(${campaignId}): dailyBudget ${currentDaily} → ${newDaily} (roas=${metrics.roas.toFixed(2)})`,
)

logger.info(
  `Admin ${req.user?.email} removed content ${contentId}. Reason: ${reason}`,
)

logger.warn({
  requestOrigin,
  allowed,
  ip: req.ip,
}, `Origin blocked: ${req.method} ${req.path}`)

logger.warn(
  {
    status: tokenResponse!.status,
    ok: tokenResponse!.ok,
    hasAccessToken: !!tokenData.access_token,
    error: tokenData.error || "none",
  },
  `[OAuth] Token exchange response for ${platform}`,
)

logger.info(
  `[SMS] Max Booster branded code sent via ${sender} to ${phoneNumber.slice(0, 5)}*** for user ${req.user.id}`,
)

logger.info(
  `🗑️ Starting permanent deletion for user ${userId} (${userEmail})`,
)

logger.info(
  `[BeatMoneyLoop] Admin user resolved: ${this._adminId} (${adminEmail})`,
)

logger.warn(
  `2FA rate limit exceeded for ${userId ? `user ${userId}` : `IP ${ip}`}`,
)

logger.info(
  `[PaymentBypass] Admin ${(req.user as Record<string, unknown>).email} deactivated payment bypass`,
)

logger.info(
  `Admin ${req.user?.email} initiated email to ${targetUser[0].email}: ${subject}`,
)

logger.info(
  `[PaymentBypass] Admin ${(req.user as Record<string, unknown>).email} activated bypass for ${durationHours}h (requested ${rawHours}h)`,
)

logger.info(
  `Admin ${req.user?.email} warned user ${userId}. Severity: ${severity}. Reason: ${reason}`,
)

logger.warn(
  `[BeatMoneyLoop] No admin user found with role='admin' AND email='${adminEmail}' — loop will be disabled until the account exists`,
)

logger.info(
  `[DNS] 📋 NS records: ${PLATFORM_NS} + ${PLATFORM_NS2} → ${DNS_SERVER_IP}`,
)

logger.info(
  `[PaymentBypass] Admin ${(req.user as Record<string, unknown>).email} extended bypass by ${additionalHours}h (requested ${rawHours}h)`,
)

logger.info(
  `Admin ${req.user?.email} tagged ticket ${ticketId}: ${cleaned.join(", ")}`,
)

logger.info(
  `🚫 Blocked IP ${ipAddress} for ${reason} (${(durationMs / 60000).toFixed(0)} minutes)`,
)

logger.info(
  `Admin ${req.user?.email} suspended user ${userId}. Reason: ${reason || "Not specified"}`,
)

logger.debug(
  {
    ip: lookupIp,
    continent: geo.continent,
    country: geo.country,
    selectedIp,
  },
  "[GeoDNS] Geo-routing query",
)

logger.warn({
  ip: req.ip,
  userAgent: req.get("user-agent"),
}, `Mutation without Origin: ${req.method} ${req.path}`)

logger.info(
  `[Dunning] Step ${step} email sent to ${email} for invoice ${invoiceId}`,
)

logger.info(
  `🚫 IP ${ipAddress} added to blacklist (${permanent ? "permanent" : `expires in ${duration / 1000}s`})`,
)

logger.info(
  `Admin ${req.user?.email} granted lifetime subscription to user ${userId}`,
)
